import random, time, subprocess, sys
from collections import deque

def ref_solve(data_bytes):
    grid = [list(line) for line in data_bytes.decode().splitlines() if line]
    h = len(grid)
    w = len(grid[0])
    s = e = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 'S': s = (r, c)
            elif grid[r][c] == 'E': e = (r, c)
    if not s or not e: return -1
    if s == e: return 0
    q = deque([(s[0], s[1], 0)])
    grid[s[0]][s[1]] = '#'
    while q:
        r, c, d = q.popleft()
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != '#':
                if (nr, nc) == e:
                    return d + 1
                grid[nr][nc] = '#'
                q.append((nr, nc, d + 1))
    return -1

def make_maze(n, seed, density=0.22):
    rng = random.Random(seed)
    # Generate random grid with density < percolation threshold (0.407 is site percolation, so 0.22 walls = 0.78 open is well connected)
    row_ bytes = bytearray(b'.#'[rng.random() < density] for _ in range(n * n))
    grid = [row_bytes[i*n:(i+1)*n] for i in range(n)]
    # Add some macro barriers to make path twisty without blocking
    for r in range(200, n - 200, 200):
        if (r // 200) % 2 == 1:
            for c in range(0, n - 200):
                grid[r][c] = 35
        else:
            for c in range(200, n):
                grid[r][c] = 35
    grid[0][0] = ord('S')
    grid[0][1] = ord('.')
    grid[1][0] = ord('.')
    grid[n-1][n-1] = ord('E')
    grid[n-1][n-2] = ord('.')
    grid[n-2][n-1] = ord('.')
    return b'\n'.join(grid) + b'\n'

